export type CategoryType = 'fast_food' | 'restaurant' | 'pub' | 'cafe';
export type ZoneType = 'dhsp2' | 'center' | 'expanded';
export type ServiceMode = 'both' | 'delivery_only' | 'dine_in_only';

export type PlaceStyleGroup = 'nhau-lau' | 'an-chinh' | 'uong' | 'an-vat';

export function getPlaceStyleGroup(place: Place): PlaceStyleGroup {
  if (
    place.category === 'pub' || 
    ['vanh-dai-quan', 'san-bia-247', 'bia-sai-gon-tuan-hien', 'trau-phi-xuyen', 'lon-ga-xuyen-phi', 'trau-gio-dong', 'trang-hai-san', 'lau-cuong-duong', 'lau-nuong-ba-muoi', 'quan-oc-ngon', 'oc-2000-xuan-hoa', 'nha-hang-khanh-huong', 'nha-hang-binh-nam', 'nha-hang-468', 'quan-chim-lan-anh', 'xuho-bistro', 'beef88-xuan-hoa', 'cuon-moc-xuan-hoa', 'lau-nuong-1968', 'xien-nuong-trung-hoa', 'lau-ngua-tay-bac'].includes(place.id)
  ) {
    return 'nhau-lau';
  }
  if (['nhungs-corner', 'ruby-quan', 'gamitra-xuan-hoa', 'xoai-corner', 'my-cay-seoul', 'thuy-beo', 'tao-pho-chi-beo', 'bep-thanh', 'mr-tea-xuan-hoa', 'tiem-lan-phuong', 'goky-xuan-hoa', 'tram-du-de', 'bm-nuong-muoi-ot-ngoc-quy', 'thi-lan-tea', 'che-xuan-mai', 'nhat-ha', 'tiem-banh-a-salty-name', 'thanh-hang-gateaux', 'banh-trang-55-nguyen-van-linh', 'quan-dua-kha-do', 'zun-food-tea'].includes(place.id)) {
    return 'an-vat';
  }
  if (
    place.category === 'cafe' || 
    ['soh-tea', 'cafe-1975-xuan-hoa', 'tiem-tra-sua-tocotoco', 'tiem-tra-thanh-thanh', 'cat-tien-xuan-hoa'].includes(place.id)
  ) {
    return 'uong';
  }
  return 'an-chinh';
}

export function getPlaceStyleLabel(style: PlaceStyleGroup): string {
  switch (style) {
    case 'nhau-lau': return 'Quán Nhậu & Lẩu Nướng';
    case 'an-chinh': return 'Quán Cơm & Bún Phở';
    case 'uong': return 'Cafe & Đồ Uống';
    case 'an-vat': return 'Quán Ăn Vặt';
  }
}

export interface MenuItem {
  id: string;
  name: string;
  price: number; // đơn vị: nghìn VNĐ (k)
  description?: string;
  tag?: string; // "Món tủ", "Bán chạy", "Thanh mát", "Đặc sản"
  serviceTag?: 'ship' | 'dine_in' | 'both'; // 'ship': Có Ship | 'dine_in': Ăn tại quán | 'both': Ship & Tại quán
  rarity?: number; // 0 - 4
}

export interface Review {
  id: string;
  author: string;
  avatar?: string;
  rating: number; // 1 - 5 sao
  date: string;
  content: string;
  role?: string; // "Sinh viên ĐHSP2", "Dân bản địa", "Khách du lịch"
}

export interface Place {
  id: string;
  name: string;
  tagline: string;
  category: CategoryType;
  zone: ZoneType;
  distance: string; // VD: "250m từ cổng ĐHSP2"
  address: string;
  priceRange: string; // VD: "20k - 45k"
  minPrice: number;
  maxPrice: number;
  rating: number; // 1.0 - 5.0
  reviewCount: number;
  imageUrl: string;
  serviceMode?: ServiceMode;
  deliveryNote?: string;
  signatureDish: MenuItem;
  menu: MenuItem[];
  tags: string[];
  mapsQuery: string;
  mapsUrl?: string;
  phone?: string;
  openHours?: string;
  rarity: number; // 0: Phổ thông, 1: Ngon rẻ, 2: Đặc sắc, 3: Cao cấp, 4: Huyền thoại / Món tủ Xuân Hòa
  quip: string; // Câu châm ngôn hài hước / review ngắn
  mealSessions?: PlaceSessionType[];
}

// Ước tính mức chi tiêu trung bình / người của quán (nghìn đồng)
export function getPlaceEstimatedPerPerson(place: Place): number {
  const style = getPlaceStyleGroup(place);
  if (style === 'nhau-lau') {
    // Nhà hàng tiệc, đặc sản lớn
    if (['trau-phi-xuyen', 'trau-gio-dong', 'trang-hai-san', 'nha-hang-468', 'lon-ga-xuyen-phi'].includes(place.id)) {
      return 180;
    }
    // Lẩu nướng, quán nhậu đêm, ốc
    if (['lau-nuong-ba-muoi', 'quan-oc-ngon', 'oc-2000-xuan-hoa', 'xuho-bistro', 'quan-chim-lan-anh', 'lau-cuong-duong', 'nha-hang-khanh-huong', 'nha-hang-binh-nam', 'cuon-moc-xuan-hoa', 'lau-nuong-1968'].includes(place.id)) {
      return 100;
    }
    return 100;
  }
  if (style === 'uong') {
    return Math.round((place.minPrice + place.maxPrice) / 2) || 28;
  }
  if (style === 'an-vat') {
    return Math.min(Math.round((place.minPrice + place.maxPrice) / 2), 40) || 30;
  }
  // an-chinh (cơm, bún, phở)
  return Math.round((place.minPrice + place.maxPrice) / 2) || 35;
}

// Phân khúc giá của quán
export function getPlacePriceTierLabel(place: Place): string {
  const est = getPlaceEstimatedPerPerson(place);
  if (est < 35) return 'Bình dân (<35k/người)';
  if (est <= 60) return 'Vừa túi (35k-60k/người)';
  if (est <= 130) return 'Lẩu & Nhậu (70k-130k/người)';
  return 'Nhà hàng & Đặc sản (>130k/người)';
}

// Danh hiệu & Nhãn phân loại thực tế của quán (Fact-based, không tâng bốc chủ quan)
export interface PlaceHonorBadge {
  label: string;
  color: string;
  bg: string;
  border: string;
  desc: string;
}

export function getPlaceHonorBadge(place: Place): PlaceHonorBadge {
  const est = getPlaceEstimatedPerPerson(place);
  const style = getPlaceStyleGroup(place);

  // 1. Quán được đông đảo thực khách đánh giá cao thực tế (Rating >= 4.85 & reviewCount >= 200)
  if (place.rating >= 4.85 && place.reviewCount >= 200) {
    return {
      label: 'Điểm Hẹn Bản Địa',
      color: '#F59E0B',
      bg: 'rgba(245, 158, 11, 0.18)',
      border: 'rgba(245, 158, 11, 0.5)',
      desc: 'Quán quen gắn bó với thực khách Xuân Hòa'
    };
  }

  // 2. Không gian bàn tiệc / liên hoan nhóm đông (thay vì chữ "Cao cấp")
  if (style === 'nhau-lau' && (est >= 120 || place.category === 'restaurant')) {
    return {
      label: 'Bàn Tiệc & Nhậu',
      color: '#A855F7',
      bg: 'rgba(168, 85, 247, 0.18)',
      border: 'rgba(168, 85, 247, 0.45)',
      desc: 'Phù hợp tiếp khách, liên hoan nhóm đông'
    };
  }

  // 3. Quán ăn vặt / Đồ uống quen thuộc
  if (style === 'an-vat' || style === 'uong') {
    return {
      label: 'Quán Trẻ & Ăn Vặt',
      color: '#E07A5F',
      bg: 'rgba(224, 122, 95, 0.18)',
      border: 'rgba(224, 122, 95, 0.45)',
      desc: 'Điểm hẹn giới trẻ & sinh viên Sư Phạm 2'
    };
  }

  // 4. Quán ăn bình dân giá sinh viên (< 45k/người)
  if (est <= 45) {
    return {
      label: 'Bình Dân Sinh Viên',
      color: '#10B981',
      bg: 'rgba(16, 185, 129, 0.18)',
      border: 'rgba(16, 185, 129, 0.45)',
      desc: 'Ăn no giá rẻ, vừa túi tiền học sinh sinh viên'
    };
  }

  // 5. Mặc định: Quán quen xác thực
  return {
    label: 'Xuân Hòa Xác Thực',
    color: '#38BDF8',
    bg: 'rgba(56, 189, 248, 0.18)',
    border: 'rgba(56, 189, 248, 0.45)',
    desc: 'Địa chỉ có thật, hoạt động năm 2026'
  };
}

// Tầm giá / người hiển thị thực tế (VNĐ)
export function getPlacePerPersonText(place: Place): string {
  if (place.id === 'cuon-moc-xuan-hoa') {
    return '~60k - 85k/người';
  }
  if (place.id === 'oc-2000-xuan-hoa') {
    return '~45k - 75k/người';
  }
  if (place.id === 'bm-nuong-muoi-ot-ngoc-quy') {
    return '~15k - 30k/người';
  }
  if (place.id === 'cat-tien-xuan-hoa') {
    return '~20k - 35k/người';
  }
  if (place.id === 'nhat-ha') {
    return '~19k - 39k/người';
  }
  if (place.id === 'vanh-dai-quan') {
    return '~80k - 150k/người';
  }
  if (place.id === 'san-bia-247') {
    return '~80k - 150k/người';
  }
  if (place.id === 'bia-sai-gon-tuan-hien') {
    return '~50k - 100k/người';
  }
  if (place.id === 'tiem-banh-a-salty-name') {
    return '~55k - 90k/người';
  }
  if (place.id === 'thanh-hang-gateaux') {
    return '~45k - 150k/người';
  }
  if (place.id === 'banh-trang-55-nguyen-van-linh') {
    return '~20k - 35k/người';
  }
  if (place.id === 'nhungs-corner') {
    return '~30k - 55k/người';
  }
  if (place.id === 'zun-food-tea') {
    return '~25k - 45k/người';
  }
  if (place.id === 'my-ga-tan-linh-duong') {
    return '~35k - 75k/người';
  }
  if (place.id === 'bep-nha-bong') {
    return '~30k - 45k/người';
  }
  if (place.id === 'cocokana-tra-trai-cay') {
    return '~25k - 35k/người';
  }
  const style = getPlaceStyleGroup(place);
  if (style === 'nhau-lau') {
    if (['trau-phi-xuyen', 'trau-gio-dong', 'trang-hai-san', 'nha-hang-468', 'lon-ga-xuyen-phi'].includes(place.id)) {
      return '~150k - 220k/người';
    }
    return '~85k - 130k/người';
  }
  if (style === 'uong') {
    return '~25k - 40k/người';
  }
  if (style === 'an-vat') {
    return '~20k - 35k/người';
  }
  return '~35k - 50k/người';
}

// Cự ly ngắn gọn và chuẩn xác từ ĐHSP2 / trung tâm Xuân Hòa
export function getPlaceShortDistance(place: Place): string {
  const dist = place.distance || '';
  const addr = place.address || '';

  if (dist.includes('< 300m')) return '< 300m ĐHSP2';
  if (dist.includes('100m')) return '~100m ĐHSP2';
  if (dist.includes('150m')) return '~150m ĐHSP2';
  if (dist.includes('250m')) return '~250m ĐHSP2';
  if (dist.includes('350m')) return '~350m ĐHSP2';
  if (dist.includes('400m')) return '~400m ĐHSP2';
  if (dist.includes('500m')) return '~500m ĐHSP2';

  const mMatch = dist.match(/(\d+)\s*m/);
  if (mMatch) return `~${mMatch[1]}m ĐHSP2`;

  const kmMatch = dist.match(/([\d.]+)\s*km/);
  if (kmMatch) return `~${kmMatch[1]}km`;

  if (addr.includes('Nguyễn Văn Linh') || dist.includes('Nguyễn Văn Linh')) return '< 250m NVL';
  if (addr.includes('Trường Chinh') || dist.includes('Trường Chinh')) return '~300m Trường Chinh';
  if (addr.includes('Lê Quang Đạo') || dist.includes('Lê Quang Đạo')) return '~450m Lê Quang Đạo';
  if (addr.includes('Trần Phú') || dist.includes('Trần Phú')) return '~500m Trần Phú';
  if (addr.includes('Con Chim Xanh') || dist.includes('Con Chim Xanh') || addr.includes('Kim Ngọc') || dist.includes('Kim Ngọc')) return '~350m Con Chim Xanh';
  if (addr.includes('Chợ') || dist.includes('Chợ')) return '~250m Dốc Chợ';
  if (addr.includes('KĐT') || dist.includes('Sinh Viên')) return '~300m KĐT Sinh Viên';

  if (place.zone === 'dhsp2') return '< 250m ĐHSP2';
  if (place.zone === 'center') return '~400m Trung tâm';
  return '~600m Xuân Hòa';
}

