export interface PlaceRecommendation {
  place: Place;
  diff: number; // chênh lệch giá ước tính: place.est - current.est
  diffLabel: string;
  badgeType: 'equal' | 'lower' | 'higher';
}

// Gợi ý các quán có giá hợp lý tương đương
export function getSimilarPricedPlaces(currentPlace: Place, allPlaces: Place[]): PlaceRecommendation[] {
  if (!currentPlace || !allPlaces || allPlaces.length <= 1) return [];

  const currentEst = getPlaceEstimatedPerPerson(currentPlace);
  const currentStyle = getPlaceStyleGroup(currentPlace);

  const pool = allPlaces.filter(p => p.id !== currentPlace.id);

  // Tính điểm phù hợp: khoảng cách giá + thưởng phong cách tương đồng
  const scored = pool.map(p => {
    const est = getPlaceEstimatedPerPerson(p);
    const diff = est - currentEst;
    const absDiff = Math.abs(diff);
    const sameStyle = getPlaceStyleGroup(p) === currentStyle;
    
    // Khoảng cách càng nhỏ càng tốt, cùng phong cách giảm 25 điểm chênh lệch
    const distanceScore = absDiff * 1.5 + (sameStyle ? 0 : 25);

    let badgeType: 'equal' | 'lower' | 'higher';
    let diffLabel = '';

    if (absDiff <= 10) {
      badgeType = 'equal';
      diffLabel = `Ngang tầm giá (~${est}k)`;
    } else if (diff < 0) {
      badgeType = 'lower';
      diffLabel = `Tiết kiệm hơn (-${absDiff}k)`;
    } else {
      badgeType = 'higher';
      diffLabel = `Nâng tầm (+${diff}k)`;
    }

    return {
      place: p,
      diff,
      diffLabel,
      badgeType,
      score: distanceScore
    };
  });

  // Sắp xếp quán có giá và phong cách tương đồng nhất lên đầu
  scored.sort((a, b) => a.score - b.score);

  return scored.slice(0, 8).map(s => ({
    place: s.place,
    diff: s.diff,
    diffLabel: s.diffLabel,
    badgeType: s.badgeType
  }));
}

